-- Synthetic local fixtures only; no provider calls, every mutation rolled back.
BEGIN;
SET search_path=public,extensions;
SELECT extensions.plan(54);
SELECT extensions.ok(to_regclass('public.hakafa_vouchers') IS NOT NULL,'independent voucher ledger exists');
INSERT INTO auth.users(id,email) VALUES ('91000000-0000-4000-8000-000000000001','voucher-admin@example.test'),('91000000-0000-4000-8000-000000000002','voucher-instructor@example.test'),('91000000-0000-4000-8000-000000000003','voucher-cashier@example.test');
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE public.profiles SET role='admin' WHERE id='91000000-0000-4000-8000-000000000001';
UPDATE public.profiles SET role='cashier' WHERE id='91000000-0000-4000-8000-000000000003';
INSERT INTO public.orders(id,order_number,client_name,client_phone,activity_date,num_participants,total_price)
VALUES('91000000-0000-4000-8000-000000000010','LOCAL-VOUCHER','Original','0500000000',current_date,1,118),('91000000-0000-4000-8000-000000000011','LOCAL-VOUCHER-OTHER','Original','0500000000',current_date,1,118);
CREATE TEMP TABLE financial_baseline AS SELECT (SELECT count(*) FROM public.sales) sales,(SELECT count(*) FROM public.payment_transactions) payments,(SELECT count(*) FROM public.accounting_events) events;
GRANT SELECT ON financial_baseline TO authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000001"}',true);
SET LOCAL ROLE authenticated;
SELECT extensions.throws_ok($$SELECT public.save_customer('{"display_name":"Synthetic"}','91000000-0000-4000-8000-000000000020',NULL)$$,'22023','explicit_vat_required','new customer requires explicit VAT');
SELECT extensions.throws_ok($$INSERT INTO public.customers(display_name) VALUES('Unknown')$$,'22023','explicit_vat_required','direct unknown VAT insert denied');
SELECT extensions.lives_ok($$SELECT public.save_customer('{"display_name":"Synthetic","billing_name":"Synthetic Billing","billing_company_id":"123456789","phone":"0500000000","vat_applicable":true}','91000000-0000-4000-8000-000000000020',NULL)$$,'save liable customer');
SELECT extensions.lives_ok($$SELECT public.link_order_customer('91000000-0000-4000-8000-000000000010','91000000-0000-4000-8000-000000000020',0)$$,'link canonical customer');
SELECT extensions.is((SELECT vat_applicable FROM public.orders WHERE id='91000000-0000-4000-8000-000000000010'),true,'VAT copied explicitly');
SELECT extensions.is((SELECT customer_snapshot_id FROM public.orders WHERE id='91000000-0000-4000-8000-000000000011'),NULL::uuid,'old unlinked order not backfilled');
SELECT extensions.throws_ok($$SELECT public.link_order_customer('91000000-0000-4000-8000-000000000010','91000000-0000-4000-8000-000000000020',0)$$,'40001','customer_version_conflict','stale order version rejected');
SELECT extensions.throws_ok($$UPDATE public.customers SET vat_applicable=NULL WHERE id='91000000-0000-4000-8000-000000000020'$$,'22023','explicit_vat_required','direct unknown VAT update denied');
SELECT extensions.lives_ok($$SELECT public.save_customer('{"display_name":"Changed","billing_name":"Changed Billing","vat_applicable":false}','91000000-0000-4000-8000-000000000020',1)$$,'canonical VAT may be explicitly reviewed');
SELECT extensions.is((SELECT vat_applicable FROM public.orders WHERE id='91000000-0000-4000-8000-000000000010'),true,'master edit does not change frozen VAT');
SELECT extensions.is((SELECT billing_institution_name FROM public.orders WHERE id='91000000-0000-4000-8000-000000000010'),'Synthetic Billing','master edit does not change frozen billing');
SELECT extensions.throws_ok($$UPDATE public.orders SET vat_applicable=false WHERE id='91000000-0000-4000-8000-000000000010'$$,'42501','customer_snapshot_immutable','direct frozen VAT mutation rejected');
SELECT extensions.throws_ok($$UPDATE public.customer_snapshots SET data='{}'$$,'42501',NULL,'direct snapshot mutation denied');
SELECT extensions.ok(NOT public.valid_voucher_signature('{"width":1,"height":1,"strokes":[[{"x":0.1,"y":0.1},{"x":0.1,"y":0.1}]]}'),'empty dot signature rejected');
SELECT extensions.ok(NOT public.valid_voucher_signature('{"width":1,"height":1,"strokes":[[{"x":-1,"y":0},{"x":1,"y":1}]]}'),'out of bounds signature rejected');
SELECT extensions.ok(NOT public.valid_voucher_signature('{"width":1,"height":1,"strokes":[],"svg":"<script/>"}'),'executable signature input rejected');
RESET ROLE;
CREATE TEMP TABLE voucher_request AS SELECT jsonb_build_object('order_id',id,'customer_snapshot_id',customer_snapshot_id,'register_code','GENERAL','service_description','Synthetic service','notes','Synthetic notes','contact_name','Signer','phone','0500000000','signature','{"width":1,"height":1,"strokes":[[{"x":0.1,"y":0.1},{"x":0.8,"y":0.7}]]}'::jsonb) data FROM public.orders WHERE id='91000000-0000-4000-8000-000000000010';
GRANT SELECT ON voucher_request TO authenticated;
SET LOCAL ROLE authenticated;
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000030',jsonb_set(data,'{register_code}','"MISSING"')) FROM voucher_request$$,'P0001','active_register_required','unknown register rejected');
SELECT extensions.lives_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000030',data) FROM voucher_request$$,'signed voucher created');
SELECT extensions.lives_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000030',data) FROM voucher_request$$,'same request replay safe');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000030',jsonb_set(data,'{notes}','"Changed"')) FROM voucher_request$$,'PT409','voucher_idempotency_conflict','changed replay rejected');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000031',data) FROM voucher_request$$,'PT409','order_voucher_exists','different key cannot duplicate same order');
SELECT extensions.is((SELECT vat_applicable FROM public.hakafa_vouchers WHERE id='91000000-0000-4000-8000-000000000030'),true,'voucher uses frozen VAT instead of latest master');
SELECT extensions.is((SELECT creator_role FROM public.hakafa_vouchers WHERE id='91000000-0000-4000-8000-000000000030'),'admin','creator role server derived');
SELECT extensions.throws_ok($$UPDATE public.hakafa_vouchers SET notes='edited'$$,'42501',NULL,'voucher immutable to staff');
SELECT extensions.is((SELECT count(*) FROM public.sales),(SELECT sales FROM financial_baseline),'voucher creates no sale');
SELECT extensions.is((SELECT count(*) FROM public.payment_transactions),(SELECT payments FROM financial_baseline),'voucher creates no payment');
SELECT extensions.is((SELECT count(*) FROM public.accounting_events),(SELECT events FROM financial_baseline),'voucher creates no accounting event');
SELECT extensions.is((SELECT payment_status FROM public.orders WHERE id='91000000-0000-4000-8000-000000000010'),U&'\05DC\05D0 \05E9\05D5\05DC\05DD','voucher leaves order unpaid');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000002"}',true);
SELECT extensions.is((SELECT count(*) FROM public.hakafa_vouchers),0::bigint,'instructors cannot read vouchers');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000032','{}')$$,'42501','voucher_access_denied','instructors cannot create vouchers');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SET LOCAL ROLE service_role;
SELECT extensions.is((public.claim_voucher_email('91000000-0000-4000-8000-000000000030','91000000-0000-4000-8000-000000000040','91000000-0000-4000-8000-000000000001','accounting@example.test')->>'claimed')::boolean,true,'email claim succeeds');
SELECT extensions.is((public.claim_voucher_email('91000000-0000-4000-8000-000000000030','91000000-0000-4000-8000-000000000040','91000000-0000-4000-8000-000000000001','accounting@example.test')->>'claimed')::boolean,false,'email dispatch claim cannot replay');
SELECT extensions.throws_ok($$SELECT public.claim_voucher_email('91000000-0000-4000-8000-000000000030','91000000-0000-4000-8000-000000000041','91000000-0000-4000-8000-000000000001','accounting@example.test')$$,'40001','voucher_email_already_prepared','different email request cannot resend');
SELECT extensions.lives_ok($$SELECT public.finish_voucher_email('91000000-0000-4000-8000-000000000040','uncertain')$$,'uncertain delivery recorded independently');
SELECT extensions.throws_ok($$SELECT public.finish_voucher_email('91000000-0000-4000-8000-000000000040','accepted')$$,'40001','email_result_immutable','uncertain result cannot be silently promoted');
SELECT extensions.throws_ok($$SELECT public.claim_voucher_email('91000000-0000-4000-8000-000000000030','91000000-0000-4000-8000-000000000040','91000000-0000-4000-8000-000000000002','accounting@example.test')$$,'42501','voucher_access_denied','email actor must be staff');
RESET ROLE;
SELECT extensions.throws_ok($$DELETE FROM public.hakafa_vouchers WHERE id='91000000-0000-4000-8000-000000000030'$$,'42501','immutable_customer_artifact','owner cannot delete immutable voucher');
SELECT extensions.throws_ok($$DELETE FROM public.customer_snapshots WHERE order_id='91000000-0000-4000-8000-000000000010'$$,'42501','immutable_customer_artifact','owner cannot delete snapshot');
SELECT extensions.is((SELECT count(*) FROM public.voucher_email_events WHERE delivery_id='91000000-0000-4000-8000-000000000040'),2::bigint,'email has claim and terminal audit events');
SELECT extensions.is((SELECT count(*) FROM public.accounting_events),(SELECT events FROM financial_baseline),'email failure creates no accounting event');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000003"}',true);
SET LOCAL ROLE authenticated;
SELECT extensions.is((SELECT count(*) FROM public.hakafa_vouchers),1::bigint,'cashier can read vouchers');
SELECT extensions.throws_ok($$SELECT public.save_cash_register('SITE_A','Synthetic site',true)$$,'42501','administrator_required','cashier cannot configure registers');
SELECT extensions.throws_ok($$SELECT public.claim_voucher_email('91000000-0000-4000-8000-000000000030','91000000-0000-4000-8000-000000000040','91000000-0000-4000-8000-000000000003','arbitrary@example.test')$$,'42501',NULL,'browser cannot choose email recipient');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000030',data) FROM voucher_request$$,'PT409','voucher_idempotency_conflict','another creator cannot replay signature request');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000001"}',true);
SELECT extensions.lives_ok($$SELECT public.save_cash_register('SITE_A','Synthetic site',true)$$,'admin may configure real register');
SELECT extensions.throws_ok($$SELECT public.save_cash_register('GENERAL','General',false)$$,'P0001','general_register_required','GENERAL cannot be disabled');
SELECT extensions.lives_ok($$SELECT public.save_customer('{"customer_kind":"organization","display_name":"No ID organization","billing_company_id":"","vat_applicable":false}','91000000-0000-4000-8000-000000000021',NULL)$$,'organization saved for review');
SELECT extensions.lives_ok($$SELECT public.link_order_customer('91000000-0000-4000-8000-000000000011','91000000-0000-4000-8000-000000000021',0)$$,'second order gets explicit exempt snapshot');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000033',data||jsonb_build_object('order_id','91000000-0000-4000-8000-000000000011','customer_snapshot_id',(SELECT customer_snapshot_id FROM public.orders WHERE id='91000000-0000-4000-8000-000000000011'))) FROM voucher_request$$,'P0001','billing_company_id_required','organization voucher requires company ID');
SELECT extensions.is((SELECT vat_applicable FROM public.orders WHERE id='91000000-0000-4000-8000-000000000011'),false,'explicit false exemption preserved');
UPDATE public.orders SET status=U&'\05D1\05D5\05D8\05DC' WHERE id='91000000-0000-4000-8000-000000000011';
SELECT extensions.throws_ok($$SELECT public.link_order_customer('91000000-0000-4000-8000-000000000011','91000000-0000-4000-8000-000000000020',1)$$,'P0001','unpaid_order_required','canceled order cannot be relinked');
SELECT extensions.throws_ok($$SELECT public.create_hakafa_voucher('91000000-0000-4000-8000-000000000033',data||jsonb_build_object('order_id','91000000-0000-4000-8000-000000000011','customer_snapshot_id',(SELECT customer_snapshot_id FROM public.orders WHERE id='91000000-0000-4000-8000-000000000011'))) FROM voucher_request$$,'P0001','unpaid_order_required','canceled order cannot create voucher');
RESET ROLE;
SELECT extensions.throws_ok($$DELETE FROM public.voucher_email_events WHERE delivery_id='91000000-0000-4000-8000-000000000040'$$,'42501','immutable_customer_artifact','email audit immutable even to table owner');
SELECT * FROM extensions.finish();
ROLLBACK;
